for _alias, _canonical in ROLE_ALIASES.items():
    ROLE_PROMPTS[_alias] = ROLE_PROMPTS[_canonical]


def build_role_prompt(role: str, mode: str, *, first_round: bool = False) -> str:
    """只替换 mode 占位符，保留 JSON 示例和 DAG 程序标识占位符。"""
    if mode not in {"Single", "Chain", "Parallel", "Tree", "DAG", "FullMesh"}:
        raise ValueError(f"未知协作拓扑：{mode}")
    template = ROLE_PROMPTS[role]
    key = "FullMesh:first" if mode == "FullMesh" and first_round else mode
    mode_prompt = MODE_PROMPTS.get(key, MODE_PROMPT.replace("{mode}", mode))
    return template.replace("{mode_prompt}", mode_prompt)
